// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 value) public {
        vm.assume(sender != address(0));
        vm.assume(value <= address(c).balance);

        address ownerBefore = c.owner();

        vm.prank(c.owner());
        c.sendMoney(sender, value);

        assertTrue(c.owner() == ownerBefore);
    }
}

